let stateCache=null;let identityCache=null;let accountCache=null;let filesCache=null;let kbCache=null;let recycleCache=null;let auditCache=null;let backupCache=null;const pageState={accounts:1,files:1,orphans:1,kb:1,recycle:1,audit:1,backup:1};const adminT=(key,fallback='')=>window.AperviaI18n?.t(key,null,fallback)||fallback;const adminTP=(key,params=null,fallback='')=>window.AperviaI18n?.t(key,params,fallback)||fallback;const adminPhrase=value=>window.AperviaI18n?.phrase(String(value??''))||String(value??'');
const ADMIN_ERROR_MESSAGE_KEYS={
  '不能停用或降级最后一个管理员':'admin.error.last_admin_disable_or_downgrade',
  '不能停用或拉黑最后一个管理员':'admin.error.last_admin_disable_or_blacklist',
  '最后一个管理员不能删除自己的账号':'admin.error.last_admin_delete_self',
};
function adminErrorText(value){const raw=String(value??'').trim();if(!raw)return '';const match=raw.match(/^([A-Za-z][A-Za-z0-9_.]*:\s*)([\s\S]*)$/);const prefix=match?match[1]:'';const message=match?match[2]:raw;const key=ADMIN_ERROR_MESSAGE_KEYS[message];return prefix+(key?adminT(key,message):adminPhrase(message))}
function esc(v){return String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]||s))}
async function requestJson(url,options={}){const opts=Object.assign({cache:'no-store'},options||{});const res=await fetch(url,opts);const data=await res.json().catch(()=>({}));if(res.status===401){location.replace('/login?next='+encodeURIComponent(location.pathname));throw new Error(adminT('admin.login_required','请先登录'))}if(!res.ok){const err=new Error(adminErrorText(data.message||data.error||adminT('common.request_failed','请求失败')));err.code=data.error||'';throw err}return data||{}}
async function postJson(url,body){return requestJson(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body||{})})}
function setMsg(t,isErr=false){const el=document.getElementById('msg');el.textContent=String(t||'');el.classList.toggle('error',!!isErr)}
function fillClass(p){const n=Number(p||0);return n>=95?'bad':(n>=80?'warn':'')}function renderBar(p){const n=Math.max(0,Math.min(100,Number(p||0)));return `<div class="bar"><div class="fill ${fillClass(n)}" style="width:${n}%"></div></div>`}
function bytesToMb(bytes){return Math.max(64,Math.round(Number(bytes||0)/1048576))}
function qs(params){const u=new URLSearchParams();Object.entries(params||{}).forEach(([k,v])=>{if(v!==undefined&&v!==null&&String(v).trim()!=='')u.set(k,String(v))});return u.toString()}
function renderPager(id,page,onPrev,onNext){const el=document.getElementById(id);if(!el)return;const p=page||{};const info=adminTP('admin.platform.pagination',{start:Number(p.start||0),end:Number(p.end||0),total:Number(p.total||0),page:Number(p.page||1),pages:Number(p.total_pages||1)});el.innerHTML=`<button type="button" ${p.has_prev?'':'disabled'} data-pager="${id}" data-dir="prev">${esc(adminT('admin.identity.previous','上一页'))}</button><span class="info">${esc(info)}</span><button type="button" ${p.has_next?'':'disabled'} data-pager="${id}" data-dir="next">${esc(adminT('admin.identity.next','下一页'))}</button>`;el._pagerHandlers={prev:onPrev,next:onNext}}
function emptyState(title,hint=''){return `<div class="emptyState"><strong>${esc(title||adminT('admin.platform.no_data','暂无数据'))}</strong>${hint?`<span>${esc(hint)}</span>`:''}</div>`}
function setAdminListLoading(ids,{rows=4,label}={}){const text=label||adminT('common.loading','正在载入…');for(const id of ids||[]){const el=document.getElementById(id);if(!el)continue;if(typeof AppLoadingUi!=='undefined')AppLoadingUi.render(el,{variant:'list',rows,label:text});else el.innerHTML=`<div class="muted">${esc(text)}</div>`}}
function clearAdminListLoading(ids){for(const id of ids||[]){const el=document.getElementById(id);if(el&&typeof AppLoadingUi!=='undefined')AppLoadingUi.ready(el)}}
async function withAdminListLoading(ids,task,options={}){setAdminListLoading(ids,options);try{return await task()}catch(err){clearAdminListLoading(ids);for(const id of ids||[]){const el=document.getElementById(id);if(el)el.innerHTML=emptyState(adminT('admin.platform.load_failed','读取失败'),String(err?.message||err||adminT('admin.platform.try_again','请稍后重试')))}throw err}}
const ADMIN_PAGE_META={overview:['admin.platform.overview_title','admin.platform.overview_subtitle'],users:['admin.identity.title','admin.identity.subtitle'],accounts:['admin.platform.accounts_title','admin.platform.accounts_subtitle'],rate:['admin.rate.title','admin.rate.subtitle'],files:['admin.platform.files_title','admin.platform.files_subtitle'],kb:['admin.platform.kb_title','admin.platform.kb_subtitle'],mcp:['admin.platform.mcp_title','admin.platform.mcp_subtitle'],recycle:['admin.platform.recycle_title','admin.platform.recycle_subtitle'],audit:['admin.platform.audit_title','admin.platform.audit_subtitle'],backup:['admin.platform.backup_title','admin.platform.backup_subtitle'],devops:['admin.platform.devops_title','admin.platform.devops_subtitle'],maintenance:['admin.platform.maintenance_title','admin.platform.maintenance_subtitle']};
function activateAdminTab(key){const target=String(key||'overview');document.querySelectorAll('.tab').forEach(button=>button.classList.toggle('active',button.dataset.tab===target));document.querySelectorAll('.panel').forEach(panel=>panel.classList.toggle('active',panel.id==='panel-'+target));const meta=ADMIN_PAGE_META[target]||ADMIN_PAGE_META.overview;document.getElementById('adminPageTitle').textContent=adminT(meta[0]);document.getElementById('adminPageSubtitle').textContent=adminT(meta[1]);document.getElementById('globalMetrics').hidden=target!=='overview';document.getElementById('globalOps').hidden=target!=='overview';if(target==='users'&&!identityCache)refreshIdentityUsers().catch(e=>setMsg(e.message||adminT('admin.platform.load_users_failed','Unable to load users'),true));if(target==='accounts'&&!accountCache)refreshAccounts().catch(e=>setMsg(e.message||adminT('admin.platform.load_accounts_failed','Unable to load accounts'),true));if(target==='rate')window.AperviaRateAdmin?.activate();if(target==='files'&&!filesCache)refreshFiles().catch(e=>setMsg(e.message||adminT('admin.platform.load_files_failed','Failed to load files'),true));if(target==='kb'&&!kbCache)refreshKb().catch(e=>setMsg(e.message||adminT('admin.platform.load_kb_failed','Failed to load knowledge bases'),true));if(target==='recycle'&&!recycleCache)refreshRecycle().catch(e=>setMsg(e.message||adminT('admin.platform.load_recycle_failed','Failed to load the recycle bin'),true));if(target==='audit'&&!auditCache)refreshAudit().catch(e=>setMsg(e.message||adminT('admin.platform.load_audit_failed','Failed to load audit records'),true));if(target==='backup'&&!backupCache)refreshBackups().catch(e=>setMsg(e.message||adminT('admin.platform.load_backups_failed','Failed to load backups'),true));}
function setupFileMobileSections(){const grid=document.querySelector('#panel-files .grid2');if(!grid||grid.classList.contains('fileColumns'))return;const sections=Array.from(grid.children).slice(0,2);if(sections.length<2)return;grid.classList.add('fileColumns');sections[0].dataset.fileSection='records';sections[0].classList.add('active');sections[1].dataset.fileSection='orphans';grid.insertAdjacentHTML('beforebegin',`<div class="fileSectionTabs"><button id="fileSectionRecordsBtn" class="active" type="button" data-file-view="records">${esc(adminT('admin.platform.file_records','File records'))}</button><button id="fileSectionOrphansBtn" type="button" data-file-view="orphans">${esc(adminT('admin.platform.unregistered_legacy_files','Unregistered legacy files'))}</button></div>`);document.querySelectorAll('[data-file-view]').forEach(button=>button.addEventListener('click',()=>{const key=button.getAttribute('data-file-view');document.querySelectorAll('[data-file-view]').forEach(item=>item.classList.toggle('active',item===button));document.querySelectorAll('[data-file-section]').forEach(section=>section.classList.toggle('active',section.getAttribute('data-file-section')===key));}));}
function updateFileSectionCounts(data){const records=document.getElementById('fileSectionRecordsBtn');const orphans=document.getElementById('fileSectionOrphansBtn');if(records)records.textContent=adminTP('admin.platform.file_records_count',{count:Number(data?.page?.total||0)});if(orphans)orphans.textContent=adminTP('admin.platform.orphan_files_count',{count:Number(data?.orphans?.page?.total||0)});}
function renderMetrics(data){const s=data.summary||{};document.getElementById('mUsers').textContent=String(s.accounts_total??s.users_total??'-');document.getElementById('mUsersSub').textContent=adminTP('admin.platform.metrics_users',{total:s.users_total||0,enabled:s.users_enabled||0,blacklisted:s.users_blacklisted||0});document.getElementById('mApp').textContent=s.app_used_text||'-';document.getElementById('mAppSub').textContent=adminTP('admin.platform.disk_remaining',{free:s.disk_free_text||'-'});document.getElementById('mFiles').textContent=String(s.registry_files||0);document.getElementById('mFilesSub').textContent=adminTP('admin.platform.metrics_files',{documents:s.kb_documents||0,over:s.accounts_over_limit||0});document.getElementById('mRecycle').textContent=String(data.recycle?.total||0);document.getElementById('mRecycleSub').textContent=adminTP('admin.platform.metrics_recycle',{size:data.recycle?.total_text||'0B',backups:data.backups?.page?.total||0})}
function renderIdentityMetrics(summary){const items=[['admin.identity.total_users',summary?.total],['admin.identity.admins',summary?.admin],['admin.identity.members',summary?.user],['admin.identity.pending',summary?.pending],['admin.identity.sessions',summary?.active_sessions]];document.getElementById('identityMetrics').innerHTML=items.map(([key,value])=>`<div class="metric"><div class="k">${esc(adminT(key))}</div><div class="v">${Number(value||0)}</div></div>`).join('')}
function renderIdentityUsers(rows){const body=document.getElementById('identityUsers');const users=Array.isArray(rows)?rows:[];if(!users.length){body.innerHTML=`<tr><td colspan="6">${emptyState(adminT('admin.platform.no_users','No users'))}</td></tr>`;return}body.innerHTML=users.map(user=>{const id=String(user.id||'');const protectedAdmin=!!user.access_protected;const disabled=protectedAdmin?'disabled':'';const action=protectedAdmin?`<span class="pill ok">${esc(adminT('admin.platform.protected_administrator','Protected administrator'))}</span>`:`<button type="button" data-identity-save="${esc(id)}">${esc(adminT('common.save','Save'))}</button>`;return `<tr><td><span class="identityName">${esc(user.name||'-')}</span><span class="identityEmail">${esc(user.email||'')}</span></td><td><select data-identity-role="${esc(id)}" ${disabled}><option value="admin" ${user.role==='admin'?'selected':''}>${esc(adminT('admin.identity.role_admin','Administrator'))}</option><option value="user" ${user.role==='user'?'selected':''}>${esc(adminT('admin.identity.role_user','User'))}</option><option value="pending" ${user.role==='pending'?'selected':''}>${esc(adminT('admin.identity.pending','Pending'))}</option></select></td><td><select data-identity-status="${esc(id)}" ${disabled}><option value="active" ${user.status==='active'?'selected':''}>${esc(adminT('admin.identity.status_active','Active'))}</option><option value="pending" ${user.status==='pending'?'selected':''}>${esc(adminT('admin.identity.pending','Pending'))}</option><option value="disabled" ${user.status==='disabled'?'selected':''}>${esc(adminT('admin.identity.status_disabled','Disabled'))}</option></select></td><td>${esc(user.last_login_at||'-')}</td><td>${esc(user.created_at||'-')}</td><td>${action}</td></tr>`}).join('')}
async function refreshIdentityUsers(){setAdminListLoading(['identityUsers'],{rows:5,label:adminT('admin.identity.reading','Loading…')});const [summaryData,userData]=await Promise.all([requestJson('/api3/admin/summary'),requestJson('/api3/admin/users')]);identityCache={summary:summaryData.summary||{},users:Array.isArray(userData.users)?userData.users:[]};renderIdentityMetrics(identityCache.summary);renderIdentityUsers(identityCache.users);clearAdminListLoading(['identityUsers']);return identityCache}
async function saveIdentityUser(id){const safeId=String(id||'');const role=document.querySelector(`[data-identity-role="${CSS.escape(safeId)}"]`)?.value;const status=document.querySelector(`[data-identity-status="${CSS.escape(safeId)}"]`)?.value;setMsg(adminT('admin.identity.updating','Updating user permissions…'));await requestJson('/api3/admin/users/'+encodeURIComponent(safeId),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({role,status})});await refreshIdentityUsers();setMsg(adminT('admin.identity.updated','User permissions updated'))}
function pctText(v){const n=Number(v||0);return (Number.isFinite(n)?n.toFixed(n%1?1:0):'0')+'%'}
function setGauge(id,pct){const el=document.getElementById(id);if(el)el.style.setProperty('--p',String(Math.max(0,Math.min(100,Number(pct||0)))))}
function serviceLine(label,svc){const ok=!!svc?.active;return `<div class="sysLine"><span><span class="serviceDot ${ok?'ok':'bad'}"></span>${esc(label)}</span><b>${esc(svc?.status_text||svc?.status||'-')}</b></div>`}
function statLine(label,value){return `<div class="sysLine"><span>${esc(label)}</span><b>${esc(value||'-')}</b></div>`}
function renderSystemStatus(system){const s=system||{};const cpu=s.cpu||{},mem=s.memory||{},swap=s.swap||{},disk=s.disk||{},net=s.network||{},proc=s.process||{},up=s.uptime||{},conn=s.connections||{},services=s.services||{};setGauge('sysCpuGauge',cpu.percent||0);setGauge('sysMemGauge',mem.percent||0);setGauge('sysSwapGauge',swap.percent||0);setGauge('sysDiskGauge',disk.percent||0);document.getElementById('sysCpuPct').textContent=pctText(cpu.percent||0);document.getElementById('sysCpuSub').textContent=`${Number(cpu.count||0)} Cores`;document.getElementById('sysMemPct').textContent=pctText(mem.percent||0);document.getElementById('sysMemSub').textContent=`${mem.used_text||'0B'} / ${mem.total_text||'0B'}`;document.getElementById('sysSwapPct').textContent=pctText(swap.percent||0);document.getElementById('sysSwapSub').textContent=`${swap.used_text||'0B'} / ${swap.total_text||'0B'}`;document.getElementById('sysDiskPct').textContent=pctText(disk.percent||0);document.getElementById('sysDiskSub').textContent=`${disk.used_text||'0B'} / ${disk.total_text||'0B'}`;const serviceEl=document.getElementById('systemServiceList');if(serviceEl)serviceEl.innerHTML=serviceLine('app3',services.app3||{});const runtimeEl=document.getElementById('systemRuntimeList');if(runtimeEl)runtimeEl.innerHTML=statLine(adminT('admin.platform.system_uptime','系统运行时间'),up.text||'-')+statLine(adminT('admin.platform.apervia_process','Apervia 进程'),adminTP('admin.platform.process_threads',{memory:proc.rss_text||'0B',threads:Number(proc.threads||0)}))+statLine(adminT('admin.platform.transfer_rate','整体速度'),adminTP('admin.platform.transfer_rate_value',{upload:net.upload_text||'0B/s',download:net.download_text||'0B/s'}))+statLine(adminT('admin.platform.total_data','总数据'),adminTP('admin.platform.total_data_value',{sent:net.tx_text||'0B',received:net.rx_text||'0B'}))+statLine(adminT('admin.platform.connections','连接数'),`TCP ${Number(conn.tcp||0)} · UDP ${Number(conn.udp||0)}`)}
function renderModules(list){const el=document.getElementById('moduleGrid');const rows=Array.isArray(list)?list:[];if(!rows.length){el.innerHTML=`<div class="muted">${esc(adminT('admin.platform.no_module_data','暂无模块数据'))}</div>`;return}el.innerHTML=rows.map(m=>`<div class="module"><div class="moduleTop"><div>${esc(adminPhrase(m.label||m.key))}</div><div class="muted small">${Number(m.percent||0)}%</div></div><div class="muted small" style="margin-top:6px">${esc(m.used_text||'0B')} / ${esc(adminPhrase(m.limit_text||'未限制'))}</div>${renderBar(m.percent)}</div>`).join('')}
function renderRisks(list){const el=document.getElementById('riskList');const rows=Array.isArray(list)?list:[];el.innerHTML=rows.map(r=>{const code=String(r.code||'').trim();const text=code?adminTP(`admin.platform.risk.${code}`,{percent:r.percent??'',count:r.count??''},r.text||''):String(r.text||'');return `<div class="row"><span class="pill ${esc(r.level||'')}">${esc(r.level||'info')}</span>${esc(text)}</div>`}).join('')||`<div class="muted">${esc(adminT('admin.platform.no_risks','暂无风险'))}</div>`}
function renderMaintenance(maintenance){const el=document.getElementById('maintenanceList');const idleEl=document.getElementById('maintenanceIdle');const data=maintenance&&typeof maintenance==='object'?maintenance:{};const idle=data.chat_async_idle||{};if(idleEl){const ok=!!idle.idle;idleEl.textContent=adminT(ok?'admin.platform.maintenance_idle':'admin.platform.maintenance_busy',ok?'后台空闲':'后台忙碌');idleEl.className='pill '+(ok?'ok':'warn');idleEl.title=adminTP('admin.platform.maintenance_counts',{active:Number(idle.active||0),waiting:Number(idle.waiting||0),not_done:Number(idle.not_done||0)});}const rows=Array.isArray(data.items)?data.items:[];if(!el)return;if(!rows.length){el.innerHTML=`<div class="muted">${esc(adminT('admin.platform.no_maintenance_data','暂无维护数据'))}</div>`;return}el.innerHTML=rows.map(item=>{const note=item.note?`<div class="muted small" style="margin-top:5px">${esc(adminPhrase(item.note))}</div>`:'';const updated=item.updated_at_text?`<div class="muted small" style="margin-top:5px">${esc(adminTP('admin.platform.maintenance_updated',{time:item.updated_at_text}))}</div>`:'';const limit=Number(item.limit_bytes||0)>0?` / ${esc(item.limit_text||'-')}`:'';return `<div class="module"><div class="moduleTop"><div>${esc(adminPhrase(item.label||item.key))}</div><div class="muted small">${esc(adminPhrase(item.kind||'file'))}</div></div><div class="muted small" style="margin-top:6px">${esc(item.used_text||'0B')}${limit}</div>${Number(item.limit_bytes||0)>0?renderBar(item.percent):''}${updated}${note}</div>`}).join('')}
function accountActionLabel(action){const key=String(action||'').trim();return adminT(`admin.platform.account_action.${key}`,key)}
function renderAccounts(data){
  accountCache=data||accountCache||{};
  const el=document.getElementById('accountList');
  clearAdminListLoading(['accountList']);
  const rows=Array.isArray(accountCache.rows)?accountCache.rows:[];
  if(!rows.length){
    el.innerHTML=`<div class="muted">${esc(adminT('admin.platform.no_accounts','No account data'))}</div>`;
    renderPager('accountPager',accountCache.page,()=>{},()=>{});
    return;
  }
  el.innerHTML=rows.map(a=>{
    const custom=!!a.custom_limit;
    const inputMb=bytesToMb(a.limit_bytes);
    const owner=esc(a.owner||'');
    const authActions=a.access_protected
      ?`<span class="pill ok">${esc(adminT('admin.platform.protected_administrator','Protected administrator'))}</span>`
      :a.account_kind==='registered'
      ?`${a.enabled
          ?`<button class="warn" data-account-action="disable" data-owner="${owner}">${esc(accountActionLabel('disable'))}</button>`
          :`<button class="ok" data-account-action="enable" data-owner="${owner}">${esc(accountActionLabel('enable'))}</button>`
        }${a.blacklisted
          ?`<button class="ok" data-account-action="unblacklist" data-owner="${owner}">${esc(accountActionLabel('unblacklist'))}</button>`
          :`<button class="bad" data-account-action="blacklist" data-owner="${owner}">${esc(accountActionLabel('blacklist'))}</button>`
        }${a.delete_pending
          ?`<button class="ok" data-account-action="restore_delete" data-owner="${owner}">${esc(accountActionLabel('restore_delete'))}</button>`
          :''
        }`
      :'';
    const usage=adminTP('admin.platform.account_usage',{used:a.used_text||'0B',limit:a.limit_text||'-',available:a.available_text||'0B',percent:Number(a.percent||0)});
    const sources=adminTP('admin.platform.account_sources',{files:a.tracked_files_text||'0B',kb:a.knowledge_base_text||'0B',chats:a.chat_store_text||'0B'});
    const login=adminTP('admin.platform.account_login',{time:a.last_login_at||'-',ip:a.last_login_ip||'-'});
    const accountLabel=adminT('admin.platform.account','Account');
    const limitLabel=adminT(custom?'admin.platform.custom_limit':'admin.platform.default_limit',custom?'Custom limit':'Default limit');
    return `<div class="row" data-account-row="${owner}"><div class="rowTop"><div><span class="pill ${esc(a.status_kind||'')}">${esc(adminPhrase(a.status||accountLabel))}</span><span class="pill">${esc(adminPhrase(a.role||accountLabel))}</span><span class="pill ${custom?'ok':''}">${esc(limitLabel)}</span><span class="mono">${owner}</span></div><div class="quotaEdit"><input type="number" min="64" step="64" value="${inputMb}" data-limit-input="${owner}"><span class="muted small">MB</span><button class="ok" type="button" data-save-limit="${owner}">${esc(adminT('common.save','Save'))}</button><button class="ghost" type="button" data-reset-limit="${owner}">${esc(adminT('admin.platform.restore_default','Restore default'))}</button><button type="button" data-account-detail="${owner}">${esc(adminT('admin.platform.details','Details'))}</button></div></div><div class="rowMeta">${esc(usage)}<br>${esc(sources)}<br>${esc(login)}</div>${renderBar(a.percent)}<div class="rowActions" style="margin-top:10px">${authActions}${a.can_purge_guest?`<button class="bad" data-purge-guest="${owner}">${esc(adminT('admin.platform.purge_guest_data','Purge unregistered guest data'))}</button>`:''}</div></div>`;
  }).join('');
  renderPager('accountPager',accountCache.page,()=>{
    pageState.accounts--;
    refreshAccounts().catch(e=>setMsg(e.message||adminT('admin.platform.load_accounts_failed','Unable to load accounts'),true));
  },()=>{
    pageState.accounts++;
    refreshAccounts().catch(e=>setMsg(e.message||adminT('admin.platform.load_accounts_failed','Unable to load accounts'),true));
  });
}
function renderFileRows(rows){return (rows||[]).map(f=>`<div class="row"><div class="rowTop"><div><div class="rowTitle">${esc(f.filename||f.saved_filename||'-')}</div><div><span class="pill">${esc(adminPhrase(f.namespace||f.source||'file'))}</span><span class="pill">${esc(adminPhrase(f.scope||'-'))}</span><span class="pill ${f.exists?'ok':'warn'}">${esc(adminT(f.exists?'admin.platform.exists':'admin.platform.missing',f.exists?'存在':'缺失'))}</span></div></div><div class="muted small">${esc(f.size_text||'0B')}</div></div><div class="rowMeta">${esc(adminTP('admin.platform.file_meta',{owner:f.owner||'-',path:f.path||'-',time:f.updated_at||'-'})).replace(/\n/g,'<br>')}</div></div>`).join('')||`<div class="muted">${esc(adminT('admin.platform.no_files','暂无文件'))}</div>`}
function renderFiles(data){filesCache=data||filesCache||{};clearAdminListLoading(['registryFiles','orphanFiles']);document.getElementById('registryFiles').innerHTML=renderFileRows(filesCache.files||[])+(filesCache.duplicates_removed?`<div class="muted small">${esc(adminTP('admin.platform.duplicates_hidden',{count:Number(filesCache.duplicates_removed||0)}))}</div>`:'');const orphans=filesCache.orphans||{};document.getElementById('orphanFiles').innerHTML=(orphans.rows||[]).map(f=>`<div class="row"><div class="rowTop"><div><div class="rowTitle">${esc(f.filename||'-')}</div><span class="pill warn">${esc(adminT('admin.platform.unregistered','未登记'))}</span><span class="pill">${esc(adminPhrase(f.root_label||'-'))}</span></div><button class="warn" type="button" data-orphan-delete="${esc(f.path||'')}">${esc(adminT('admin.platform.move_to_recycle','移入回收站'))}</button></div><div class="rowMeta">${esc(f.size_text||'0B')}　${esc(f.mtime||'-')}<br>${esc(f.path||'-')}</div></div>`).join('')||`<div class="muted">${esc(adminT('admin.platform.no_unregistered_files','暂无未登记旧文件'))}</div>`;renderPager('filePager',filesCache.page,()=>{pageState.files--;refreshFiles().catch(e=>setMsg(e.message||adminT('admin.platform.load_files_failed','读取文件失败'),true))},()=>{pageState.files++;refreshFiles().catch(e=>setMsg(e.message||adminT('admin.platform.load_files_failed','读取文件失败'),true))});renderPager('orphanPager',orphans.page,()=>{pageState.orphans--;refreshFiles().catch(e=>setMsg(e.message||adminT('admin.platform.load_files_failed','读取文件失败'),true))},()=>{pageState.orphans++;refreshFiles().catch(e=>setMsg(e.message||adminT('admin.platform.load_files_failed','读取文件失败'),true))})}
function renderKb(data){kbCache=data||kbCache||{};clearAdminListLoading(['kbDocs']);const rows=Array.isArray(kbCache.rows)?kbCache.rows:[];document.getElementById('kbDocs').innerHTML=rows.map(d=>`<div class="row"><div class="rowTop"><div><div class="rowTitle">${esc(d.filename||'-')}</div><span class="pill">${esc(adminPhrase(d.space_name||'默认知识库'))}</span><span class="pill ${d.parse_status==='indexed'?'ok':'warn'}">${esc(adminPhrase(d.parse_status||'-'))}</span></div><div class="muted small">${esc(d.size_text||'0B')}</div></div><div class="rowMeta">${esc(adminTP('admin.platform.kb_document_meta',{owner:d.owner||'-',chunks:Number(d.chunk_count||0),chars:Number(d.char_count||0),time:d.updated_at||'-'})).replace(/\n/g,'<br>')}</div></div>`).join('')||`<div class="muted">${esc(adminT('admin.platform.no_kb_documents','暂无知识库文档'))}</div>`;renderPager('kbPager',kbCache.page,()=>{pageState.kb--;refreshKb().catch(e=>setMsg(e.message||adminT('admin.platform.load_kb_failed','读取知识库失败'),true))},()=>{pageState.kb++;refreshKb().catch(e=>setMsg(e.message||adminT('admin.platform.load_kb_failed','读取知识库失败'),true))})}
function recycleSourceLabel(value){const label={file_library:'资料库',knowledge_document:'知识库',orphan_file:'未登记旧文件',managed_file:'应用文件'}[String(value||'')]||'应用文件';return adminPhrase(label)}
function renderRecycle(data){recycleCache=data||recycleCache||{};clearAdminListLoading(['recycleFiles']);document.getElementById('recycleFiles').innerHTML=(recycleCache.rows||[]).map(r=>{const count=Math.max(1,Number(r.artifact_count||0)||1);const missing=Math.max(0,Number(r.missing_count||0)||0);const disabledTitle=missing?`disabled title="${esc(adminT('admin.platform.incomplete_cannot_restore','文件实体不完整，不能恢复'))}"`:'';return `<div class="row"><div class="rowTop"><div><div class="rowTitle">${esc(r.filename||'-')}</div><span class="pill warn">${esc(recycleSourceLabel(r.source_kind))}</span><span class="pill">${esc(adminTP('admin.platform.file_count',{count}))}</span>${missing?`<span class="pill bad">${esc(adminTP('admin.platform.missing_entities',{count:missing}))}</span>`:''}</div><div class="rowActions"><button class="ok" data-recycle-id="${esc(r.id)}" data-recycle-action="restore" ${disabledTitle}>${esc(adminT('admin.platform.restore','恢复'))}</button><button class="bad" data-recycle-id="${esc(r.id)}" data-recycle-action="purge">${esc(adminT('admin.platform.delete_permanently','彻底删除'))}</button></div></div><div class="rowMeta">${esc(adminTP('admin.platform.recycle_meta',{size:r.size_text||'0B',time:r.recycled_at||'-',path:r.original_path||'-',reason:r.reason||'-'})).replace(/\n/g,'<br>')}</div></div>`}).join('')||`<div class="muted">${esc(adminT('admin.platform.recycle_empty','回收站为空'))}</div>`;renderPager('recyclePager',recycleCache.page,()=>{pageState.recycle--;refreshRecycle().catch(e=>setMsg(e.message||adminT('admin.platform.load_recycle_failed','读取回收站失败'),true))},()=>{pageState.recycle++;refreshRecycle().catch(e=>setMsg(e.message||adminT('admin.platform.load_recycle_failed','读取回收站失败'),true))})}
function renderAudit(data){auditCache=data||auditCache||{};clearAdminListLoading(['auditList']);const rows=Array.isArray(auditCache.rows)?auditCache.rows:[];document.getElementById('auditList').innerHTML=rows.map(a=>`<div class="row"><div class="rowTop"><div><span class="pill ${a.ok?'ok':'bad'}">${esc(adminT(a.ok?'admin.platform.status_success':'admin.platform.status_failed',a.ok?'成功':'失败'))}</span><span class="mono">${esc(adminPhrase(a.action||'-'))}</span></div><div class="muted small">${esc(a.time||'-')}</div></div><div class="rowMeta">${esc(adminTP('admin.platform.audit_meta',{target:a.target||'-',source:a.actor?.ip||'-'})).replace(/\n/g,'<br>')}${a.error?`<br>${esc(adminTP('admin.platform.error_value',{error:adminErrorText(a.error)}))}`:''}</div></div>`).join('')||`<div class="muted">${esc(adminT('admin.platform.no_audit_records','暂无审计记录'))}</div>`;renderPager('auditPager',auditCache.page,()=>{pageState.audit--;refreshAudit().catch(e=>setMsg(e.message||adminT('admin.platform.load_audit_failed','读取审计失败'),true))},()=>{pageState.audit++;refreshAudit().catch(e=>setMsg(e.message||adminT('admin.platform.load_audit_failed','读取审计失败'),true))})}
function renderBackups(data){backupCache=data||backupCache||{};clearAdminListLoading(['backupList']);document.getElementById('backupList').innerHTML=(backupCache.rows||[]).map(b=>`<div class="row"><div class="rowTop"><div><div class="rowTitle">${esc(b.id||b.filename||'-')}</div><span class="pill">${esc(adminTP('admin.platform.item_count',{count:b.entries_count||0}))}</span><span class="pill">${esc(b.size_text||'0B')}</span></div><div class="rowActions"><button class="warn" type="button" data-backup-restore="${esc(b.id||'')}">${esc(adminT('admin.platform.restore','恢复'))}</button><button class="bad" type="button" data-backup-delete="${esc(b.id||'')}">${esc(adminT('common.delete','删除'))}</button></div></div><div class="rowMeta">${esc(adminTP('admin.platform.backup_meta',{time:b.created_at_text||'-',reason:b.reason||'-',note:b.note||''})).replace(/\n/g,'<br>')}</div></div>`).join('')||`<div class="muted">${esc(adminT('admin.platform.no_backups','暂无备份'))}</div>`;renderPager('backupPager',backupCache.page,()=>{pageState.backup--;refreshBackups().catch(e=>setMsg(e.message||adminT('admin.platform.load_backups_failed','读取备份失败'),true))},()=>{pageState.backup++;refreshBackups().catch(e=>setMsg(e.message||adminT('admin.platform.load_backups_failed','读取备份失败'),true))})}
function adminChatContentText(content){try{if(typeof content==='string')return content;if(Array.isArray(content)){return content.map(item=>{if(!item||typeof item!=='object')return String(item??'');if(item.type==='text')return String(item.text||'');if(item.type==='image_url')return adminTP('admin.platform.content_image',{value:String(item.image_url?.url||item.url||'')});if(item.type==='file')return adminTP('admin.platform.content_file',{value:String(item.filename||item.name||'')});return JSON.stringify(item,null,2)}).join('\n')}if(content&&typeof content==='object'){const kind=String(content._kind||content.kind||'').trim();if(content.text)return String(content.text);if(content.answer)return String(content.answer);if(content.filename)return adminTP('admin.platform.content_file',{value:content.filename});if(kind)return `[${kind}]\n`+JSON.stringify(content,null,2);return JSON.stringify(content,null,2)}return String(content??'')}catch(_){return String(content??'')}}
function renderAdminChatMessages(session){const all=Array.isArray(session?.messages)?session.messages:[];const messages=all.filter(m=>['user','assistant'].includes(String(m?.role||'').trim().toLowerCase()));if(!messages.length)return `<div class="muted">${esc(adminT('admin.platform.no_chat_messages','暂无可展示的用户/助手消息'))}</div>`;return messages.map((m,idx)=>{const role=String(m?.role||'message').trim().toLowerCase();const when=String(m?.created_at||m?.createdAt||m?.updated_at||m?.updatedAt||'');return `<div class="row"><div class="rowTop"><div><span class="pill">${esc(adminPhrase(role))}</span><span class="muted small">${idx+1}</span></div><div class="muted small">${esc(when)}</div></div><div class="rowMeta" style="white-space:pre-wrap">${esc(adminChatContentText(m?.content))}</div></div>`}).join('')}
function renderAdminChatSession(data){const el=document.getElementById('accountDetail');if(!el)return;let box=document.getElementById('chatSessionBody');if(!box){el.insertAdjacentHTML('beforeend','<div id="chatSessionBody" class="row" style="margin-top:12px"></div>');box=document.getElementById('chatSessionBody')}const s=data.summary||{};box.innerHTML=`<div class="rowTop"><div><h3 style="margin:0">${esc(s.title||adminT('admin.platform.new_chat','新会话'))}</h3><div class="rowMeta">${esc(adminTP('admin.platform.chat_session_meta',{owner:data.owner||'-',messages:Number(s.message_count||0),model:s.model||'-',status:adminT(s.deleted?'admin.platform.status_deleted':'admin.platform.status_normal',s.deleted?'已删除':'正常'),time:s.updated_at||'-'})).replace(/\n/g,'<br>')}</div></div><button type="button" data-chat-session-close="1">${esc(adminT('admin.platform.close_content','关闭正文'))}</button></div><div class="list" style="margin-top:10px">${renderAdminChatMessages(data.session||{})}</div>`}
async function openChatSession(owner,sessionId){const reason=(prompt(adminT('admin.platform.view_reason_prompt','查看原因（会写入审计，不记录正文）'),adminT('admin.platform.admin_review','后台查看'))||'').trim();if(!reason)return;setMsg(adminT('admin.platform.chat_content_loading','正在读取会话正文…'));const data=await requestJson('/api3/platform-admin/chat-session?'+qs({owner,session_id:sessionId,reason}));renderAdminChatSession(data);setMsg(adminT('admin.platform.chat_content_loaded','已读取会话正文'))}
function renderState(data){stateCache=data||{};renderMetrics(stateCache);renderSystemStatus(stateCache.system_status||{});renderRisks(stateCache.risk_items||[]);renderModules(stateCache.modules||[]);renderMaintenance(stateCache.maintenance||{});if(stateCache.recycle)renderRecycle(stateCache.recycle);if(stateCache.audit)renderAudit(stateCache.audit);if(stateCache.backups)renderBackups(stateCache.backups);setMsg(stateCache.updated_at_text?adminTP('admin.platform.last_updated',{time:stateCache.updated_at_text}):'')}
function asList(v){return (Array.isArray(v)?v:[]).map(x=>String(x??'').trim()).filter(Boolean)}
async function refreshState(){const data=await requestJson('/api3/platform-admin/state');renderState(data);return data}
async function refreshAccounts(){return withAdminListLoading(['accountList'],async()=>{const q=String(document.getElementById('accountFilter')?.value||'').trim();const status=String(document.getElementById('accountStatus')?.value||'').trim();const data=await requestJson('/api3/platform-admin/accounts?'+qs({page:pageState.accounts,page_size:adminListPageSize(),q,status}));renderAccounts(data);return data},{rows:4,label:adminT('admin.platform.loading_accounts','Loading accounts…')})}
async function refreshFiles(){return withAdminListLoading(['registryFiles','orphanFiles'],async()=>{const owner=String(document.getElementById('fileOwnerFilter')?.value||'').trim();const q=String(document.getElementById('fileQueryFilter')?.value||'').trim();const data=await requestJson('/api3/platform-admin/files?'+qs({page:pageState.files,page_size:adminListPageSize(),orphan_page:pageState.orphans,orphan_page_size:adminListPageSize(),owner,q}));renderFiles(data);updateFileSectionCounts(data);return data},{rows:4,label:adminT('admin.platform.loading_files','Loading files…')})}
async function refreshKb(){return withAdminListLoading(['kbDocs'],async()=>{const owner=String(document.getElementById('kbOwnerFilter')?.value||'').trim();const q=String(document.getElementById('kbQueryFilter')?.value||'').trim();const data=await requestJson('/api3/platform-admin/kb?'+qs({page:pageState.kb,page_size:adminListPageSize(),owner,q}));renderKb(data);return data},{rows:4,label:adminT('admin.platform.loading_kb','Loading knowledge bases…')})}
async function refreshRecycle(){return withAdminListLoading(['recycleFiles'],async()=>{const q=String(document.getElementById('recycleQueryFilter')?.value||'').trim();const data=await requestJson('/api3/platform-admin/recycle?'+qs({page:pageState.recycle,page_size:adminListPageSize(),q}));renderRecycle(data);return data},{rows:4,label:adminT('admin.platform.loading_recycle','Loading recycle bin…')})}
async function refreshAudit(){return withAdminListLoading(['auditList'],async()=>{const target=String(document.getElementById('auditTargetFilter')?.value||'').trim();const q=String(document.getElementById('auditQueryFilter')?.value||'').trim();const data=await requestJson('/api3/platform-admin/audit?'+qs({page:pageState.audit,page_size:adminListPageSize(),target,q}));renderAudit(data);return data},{rows:4,label:adminT('admin.platform.loading_audit','Loading audit records…')})}
async function refreshBackups(){return withAdminListLoading(['backupList'],async()=>{const q=String(document.getElementById('backupQueryFilter')?.value||'').trim();const data=await requestJson('/api3/platform-admin/backups?'+qs({page:pageState.backup,page_size:adminListPageSize(),q}));renderBackups(data);return data},{rows:4,label:adminT('admin.platform.loading_backups','Loading backups…')})}
async function syncFiles(){setMsg(adminT('admin.platform.syncing_files','正在同步历史文件库…'));const data=await postJson('/api3/platform-admin/file-library-sync',{force:true});renderFiles(data);await refreshState();const r=data.sync||{};setMsg(adminTP('admin.platform.sync_complete',{scanned:r.scanned||0,added:r.added||0,owners:r.updated_owner||0}))}
function renderLegacyMigrationResult(data){
  const box=document.getElementById('legacyMigrationResult');
  if(!box)return;
  const d=data||{};
  const roots=Array.isArray(d.roots)?d.roots:[];
  const files=Array.isArray(d.files)?d.files:[];
  const dup=Array.isArray(d.duplicate_files)?d.duplicate_files:[];
  const errs=Array.isArray(d.errors)?d.errors:[];
  const title=adminT(d.dry_run?'admin.platform.migration_preview_title':'admin.platform.migration_result_title',d.dry_run?'旧目录迁移预览':'旧目录迁移结果');
  const summary=adminTP('admin.platform.migration_summary',{scanned:Number(d.scanned||0),moved:Number(d.moved||0),size:d.planned_text||d.moved_text||'0B',duplicates:Number(d.duplicates||0),truncation:adminT(d.truncated?'admin.platform.truncated':'admin.platform.not_truncated',d.truncated?'已截断':'未截断')});
  const rootCards=roots.map(r=>{const meta=adminTP('admin.platform.migration_root_meta',{root:r.root||'-',target:r.target_root||'-',scanned:Number(r.scanned||0),planned:Number(r.planned||0)});return `<div class="module"><div class="moduleTop"><div class="label">${esc(adminPhrase(r.label||r.key||'-'))}</div><span class="pill ${r.skipped?'warn':'ok'}">${esc(adminT(r.skipped?'admin.platform.skipped':'admin.platform.scanned',r.skipped?'跳过':'扫描'))}</span></div><div class="rowMeta">${esc(meta).replace(/\n/g,'<br>')}${r.reason?`<br>${esc(adminTP('admin.platform.reason_value',{reason:adminPhrase(r.reason)}))}`:''}</div></div>`}).join('')||`<div class="muted">${esc(adminT('admin.platform.no_legacy_directories','没有发现旧目录'))}</div>`;
  const fileBlock=files.length?`<h3 style="margin-top:12px">${esc(adminT('admin.platform.migration_files','迁移文件'))}</h3><div class="list">${files.slice(0,8).map(f=>`<div class="row"><div class="rowTitle">${esc(f.filename||'-')} → ${esc(f.target_filename||'-')}</div><div class="rowMeta">${esc(f.size_text||'0B')}<br>${esc(f.source||'-')}<br>${esc(f.target||'-')}</div></div>`).join('')}${files.length>8?`<div class="muted small">${esc(adminTP('admin.platform.more_collapsed',{count:files.length-8}))}</div>`:''}</div>`:'';
  const duplicateBlock=dup.length?`<h3 style="margin-top:12px">${esc(adminT('admin.platform.duplicate_files','重复文件'))}</h3><div class="rowMeta">${esc(adminTP('admin.platform.duplicate_files_hint',{count:dup.length}))}</div>`:'';
  const errorBlock=errs.length?`<h3 style="margin-top:12px">${esc(adminT('admin.platform.errors','错误'))}</h3><div class="list">${errs.slice(0,8).map(e=>`<div class="row"><span class="pill bad">${esc(adminT('admin.platform.errors','错误'))}</span><div class="rowMeta">${esc(e.source||e.root||'-')}<br>${esc(adminErrorText(e.error||'-'))}</div></div>`).join('')}</div>`:'';
  box.style.display='block';
  box.innerHTML=`<h3>${esc(title)}</h3><div class="rowMeta">${esc(summary)}</div><div class="grid3" style="margin-top:10px">${rootCards}</div>${fileBlock}${duplicateBlock}${errorBlock}`;
}
async function migrateLegacyFiles(dryRun=true){const preview=!!dryRun;setMsg(adminT(preview?'admin.platform.migration_previewing':'admin.platform.migration_running',preview?'正在预览旧目录迁移…':'正在执行旧目录迁移…'));if(!preview&&!confirm(adminT('admin.platform.migration_confirm','确认执行旧目录迁移？旧文件会移动到新目录，重复文件会去重，空旧目录会被删除。执行前建议已看过预览结果。')))return;const data=await postJson('/api3/platform-admin/migrate-legacy-files',{dry_run:preview,default_scope:'local',delete_empty_dirs:true,remove_duplicates:true,max_files:5000});renderLegacyMigrationResult(data);if(!preview){await refreshFiles();await refreshState();}setMsg(adminTP(preview?'admin.platform.migration_preview_complete':'admin.platform.migration_complete',{moved:Number(data.moved||0),duplicates:Number(data.duplicates||0),size:preview?(data.planned_text||'0B'):(data.moved_text||'0B')}))}
async function saveLimit(owner){const input=document.querySelector(`[data-limit-input="${CSS.escape(owner)}"]`);const mb=Math.max(64,Number(input?.value||0));setMsg(adminT('admin.platform.account_limit_saving','正在保存账号额度…'));await postJson('/api3/storage-admin/account-limit',{owner,limit_bytes:Math.round(mb*1048576)});await refreshAccounts();await refreshState();setMsg(adminT('admin.platform.account_limit_saved','已保存账号额度'))}
async function resetLimit(owner){setMsg(adminT('admin.platform.account_limit_resetting','正在恢复默认额度…'));await postJson('/api3/storage-admin/account-limit',{owner,reset:true});await refreshAccounts();await refreshState();setMsg(adminT('admin.platform.account_limit_reset','已恢复默认额度'))}
async function cleanup(){setMsg(adminT('admin.platform.cleanup_running','正在清理缓存/临时文件…'));await postJson('/api3/storage-admin/cleanup',{});await refreshState();setMsg(adminT('admin.platform.cleanup_complete','已清理缓存/临时文件'))}
async function safeMaintenance(){setMsg(adminT('admin.platform.safe_maintenance_running','正在执行安全维护…'));const data=await postJson('/api3/storage-admin/maintenance',{mode:'safe'});await refreshState();setMsg(adminTP('admin.platform.safe_maintenance_complete',{size:data.maintenance?.freed_text||'0B'}))}
async function deepMaintenance(target='all'){const safeTarget=String(target||'all').trim()||'all';const safeLabel=adminT(`admin.platform.maintenance_target.${safeTarget}`,safeTarget);setMsg(adminTP('admin.platform.deep_maintenance_preparing',{label:safeLabel}));const data=await postJson('/api3/storage-admin/maintenance',{mode:'deep',target:safeTarget});await refreshState();const r=data.maintenance_result||data.maintenance?.last_result||{};setMsg(adminTP('admin.platform.deep_maintenance_complete',{label:safeLabel,size:r.freed_text||data.maintenance?.freed_text||'0B'}))}
async function accountAction(owner,action){const label=accountActionLabel(action);if(!confirm(adminTP('admin.platform.account_action_confirm',{action:label,owner})))return;setMsg(adminTP('admin.platform.account_action_running',{action:label}));const reason=action==='blacklist'?prompt(adminT('admin.platform.blacklist_reason_prompt','拉黑原因，可留空'),'admin')||'admin':'';await postJson('/api3/platform-admin/account-action',{email:owner,action,reason});await refreshAccounts();await refreshState();setMsg(adminTP('admin.platform.account_action_complete',{action:label}))}
function accountPurgeSummary(data){const counts=data?.counts||{};const storage=data?.storage||{};const scope=adminT(data?.shared_anonymous_bucket?'admin.platform.purge_scope_shared':'admin.platform.purge_scope_guest',data?.shared_anonymous_bucket?'这是所有未识别访问者共用的 anonymous 数据桶。':'这是没有注册记录的游客数据归属。');return adminTP('admin.platform.purge_summary',{scope,async_jobs:Number(counts.async_jobs||0),knowledge_documents:Number(counts.knowledge_documents||0),file_records:Number(counts.file_records||0),sandbox_files:Number(counts.sandbox_files||0),chat_backups:Number(counts.chat_backups||0),used:storage.used_text||'0B'})}
async function purgeGuestAccount(owner){const ownerKey=String(owner||'').trim().toLowerCase();if(!ownerKey)return;setMsg(adminT('admin.platform.purge_checking','正在核对游客数据范围…'));const preview=await requestJson('/api3/platform-admin/account-purge-preview?'+qs({email:ownerKey}));const typed=prompt(`${accountPurgeSummary(preview)}\n\n${adminTP('admin.platform.purge_type_confirm',{owner:ownerKey})}`,'');if(typed===null){setMsg(adminT('admin.platform.delete_cancelled','已取消删除'));return}if(String(typed||'').trim().toLowerCase()!==ownerKey){throw new Error(adminT('admin.platform.purge_owner_mismatch','输入的归属标识与目标游客数据不一致'))}if(!confirm(adminTP('admin.platform.purge_final_confirm',{owner:ownerKey}))){setMsg(adminT('admin.platform.delete_cancelled','已取消删除'));return}setMsg(adminT('admin.platform.purge_running','正在永久清除游客全部信息…'));await postJson('/api3/platform-admin/account-action',{email:ownerKey,action:'purge_guest',confirm_email:typed});const detail=document.getElementById('accountDetail');if(detail)detail.innerHTML=esc(adminT('admin.platform.purge_detail_complete','该未注册游客数据已永久清除。'));await refreshAccounts();await refreshState();setMsg(adminT('admin.platform.purge_complete','未注册游客的全部关联信息已永久清除'))}
async function orphanDelete(path){if(!confirm(adminTP('admin.platform.orphan_recycle_confirm',{path})))return;const fallbackReason=adminT('admin.platform.unused_legacy_file','无用旧文件');const reason=prompt(adminT('admin.platform.delete_reason_prompt','删除原因，可留空'),fallbackReason)||fallbackReason;setMsg(adminT('admin.platform.moving_to_recycle','正在移入回收站…'));const data=await postJson('/api3/platform-admin/orphan-delete',{path,reason});renderFiles(data.files);renderRecycle(data.recycle);await refreshState();setMsg(adminT('admin.platform.moved_to_recycle','已移入回收站'))}
async function recycleVisibleOrphans(){const rows=Array.isArray(filesCache?.orphans?.rows)?filesCache.orphans.rows:[];const paths=rows.map(x=>String(x.path||'').trim()).filter(Boolean);if(!paths.length){setMsg(adminT('admin.platform.no_orphans_to_recycle','当前没有可回收的未登记文件'));return}if(!confirm(adminTP('admin.platform.recycle_orphans_confirm',{count:paths.length})))return;const fallbackReason=adminT('admin.platform.batch_orphan_cleanup','批量清理未登记旧文件');const reason=prompt(adminT('admin.platform.recycle_reason_prompt','回收原因，可留空'),fallbackReason)||fallbackReason;setMsg(adminT('admin.platform.batch_recycle_running','正在批量移入回收站…'));const data=await postJson('/api3/platform-admin/orphan-batch-delete',{paths,reason});renderFiles(data.files);renderRecycle(data.recycle);await refreshState();setMsg(adminTP('admin.platform.batch_recycle_complete',{count:Number(data.recycled||0),errors:Array.isArray(data.errors)&&data.errors.length?adminT('admin.platform.partial_failures','; some operations failed, see Audit'):''}))}
async function recycleAction(id,action){const label=adminT(action==='restore'?'admin.platform.restore':'admin.platform.delete_permanently',action==='restore'?'恢复':'彻底删除');if(!confirm(adminTP('admin.platform.recycle_action_confirm',{action:label})))return;setMsg(adminTP('admin.platform.action_running',{action:label}));const data=await postJson('/api3/platform-admin/recycle-action',{id,action});renderRecycle(data.recycle);if(data.files)renderFiles(data.files);await refreshState();setMsg(adminTP('admin.platform.action_complete',{action:label}))}
async function createBackup(){const reason=prompt(adminT('admin.platform.backup_reason_prompt','备份原因，可留空'),'manual')||'manual';setMsg(adminT('admin.platform.backup_creating','正在创建备份…'));await postJson('/api3/platform-admin/backup-create',{reason});await refreshBackups();await refreshState();setMsg(adminT('admin.platform.backup_created','备份已创建'))}
async function restoreBackup(id){if(!confirm(adminTP('admin.platform.restore_backup_confirm',{id})))return;setMsg(adminT('admin.platform.backup_restoring','正在校验并恢复备份…'));const data=await postJson('/api3/platform-admin/backup-restore',{id});await refreshBackups();await refreshState();const reloadErrors=Array.isArray(data.reload_errors)?data.reload_errors.length:0;setMsg(data.restart_required?adminTP('admin.platform.backup_restored_restart',{errors:reloadErrors?adminTP('admin.platform.runtime_reload_errors',{count:reloadErrors}):''}):adminT('admin.platform.backup_restored','备份恢复完成'))}
async function deleteBackup(id){if(!confirm(adminTP('admin.platform.delete_backup_confirm',{id})))return;setMsg(adminT('admin.platform.backup_deleting','正在删除备份…'));const data=await postJson('/api3/platform-admin/backup-delete',{id});renderBackups(data.backups);await refreshState();setMsg(adminTP('admin.platform.backup_deleted',{size:data.freed_text||'0B'}))}
async function clearBackups(){const q=String(document.getElementById('backupQueryFilter')?.value||'').trim();const scope=adminT(q?'admin.platform.filtered_backups':'admin.platform.all_backups',q?'当前搜索结果里的备份':'所有备份');if(!confirm(adminTP('admin.platform.clear_backups_confirm',{scope})))return;setMsg(adminT('admin.platform.backup_deleting','正在删除备份…'));const data=await postJson('/api3/platform-admin/backups-clear',{q});renderBackups(data.backups);await refreshState();setMsg(adminTP('admin.platform.backups_deleted',{count:Number(data.deleted||0),size:data.freed_text||'0B'}))}
async function clearRecycle(){const q=String(document.getElementById('recycleQueryFilter')?.value||'').trim();const scope=adminT(q?'admin.platform.filtered_recycle_files':'admin.platform.all_recycle_files',q?'当前搜索结果里的回收站文件':'全部回收站文件');if(!confirm(adminTP('admin.platform.clear_recycle_confirm',{scope})))return;setMsg(adminT('admin.platform.recycle_clearing','正在清空回收站…'));const data=await postJson('/api3/platform-admin/recycle-clear',{q});renderRecycle(data.recycle);if(data.files)renderFiles(data.files);await refreshState();setMsg(adminTP('admin.platform.recycle_cleared',{count:Number(data.purged||0),size:data.freed_text||'0B'}))}
async function clearAudit(){const target=String(document.getElementById('auditTargetFilter')?.value||'').trim();const q=String(document.getElementById('auditQueryFilter')?.value||'').trim();const scope=adminT((target||q)?'admin.platform.filtered_audit_records':'admin.platform.all_audit_records',(target||q)?'当前筛选条件匹配的审计记录':'全部审计记录');if(!confirm(adminTP('admin.platform.clear_audit_confirm',{scope})))return;setMsg(adminT('admin.platform.audit_clearing','正在清空审计…'));const data=await postJson('/api3/platform-admin/audit-clear',{target,q});renderAudit(data.audit);await refreshState();setMsg(adminTP('admin.platform.audit_cleared',{count:Number(data.cleared||0)}))}
document.querySelectorAll('.tab').forEach(btn=>btn.addEventListener('click',()=>activateAdminTab(btn.dataset.tab)));
