document.getElementById('reloadAccountsBtn').addEventListener('click',()=>{pageState.accounts=1;refreshAccounts().catch(e=>setMsg(e.message||adminT('admin.platform.load_accounts_failed','Unable to load accounts'),true))});
document.getElementById('reloadFilesBtn').addEventListener('click',()=>{pageState.files=1;pageState.orphans=1;refreshFiles().catch(e=>setMsg(e.message||adminT('admin.platform.load_files_failed','Failed to load files'),true))});
document.getElementById('previewLegacyMigrationFilesBtn').addEventListener('click',()=>migrateLegacyFiles(true).catch(e=>setMsg(e.message||adminT('admin.platform.migration_preview_failed','Migration preview failed'),true)));
document.getElementById('runLegacyMigrationFilesBtn').addEventListener('click',()=>migrateLegacyFiles(false).catch(e=>setMsg(e.message||adminT('admin.platform.migration_failed','Migration failed'),true)));
document.getElementById('recycleAllOrphansBtn').addEventListener('click',()=>recycleVisibleOrphans().catch(e=>setMsg(e.message||adminT('admin.platform.batch_recycle_failed','Bulk recycle failed'),true)));
document.getElementById('reloadKbBtn').addEventListener('click',()=>{pageState.kb=1;refreshKb().catch(e=>setMsg(e.message||adminT('admin.platform.load_kb_failed','Failed to load knowledge bases'),true))});
document.getElementById('reloadRecycleBtn').addEventListener('click',()=>{pageState.recycle=1;refreshRecycle().catch(e=>setMsg(e.message||adminT('admin.platform.load_recycle_failed','Failed to load the recycle bin'),true))});
