document.getElementById('reloadBackupBtn').addEventListener('click',()=>{pageState.backup=1;refreshBackups().catch(e=>setMsg(e.message||adminT('admin.platform.load_backups_failed','Failed to load backups'),true))});
document.getElementById('createBackupBtn').addEventListener('click',()=>createBackup().catch(e=>setMsg(e.message||adminT('admin.platform.create_backup_failed','Unable to create backup'),true)));
document.getElementById('clearBackupsBtn').addEventListener('click',()=>clearBackups().catch(e=>setMsg(e.message||adminT('admin.platform.delete_backup_failed','Unable to delete backups'),true)));
document.getElementById('clearRecycleBtn').addEventListener('click',()=>clearRecycle().catch(e=>setMsg(e.message||adminT('admin.platform.clear_recycle_failed','Unable to clear the recycle bin'),true)));
document.getElementById('clearAuditBtn').addEventListener('click',()=>clearAudit().catch(e=>setMsg(e.message||adminT('admin.platform.clear_audit_failed','Unable to clear audit records'),true)));
document.addEventListener('click',(e)=>{
  const pg=e.target.closest('[data-pager]');if(pg){const wrap=document.getElementById(pg.getAttribute('data-pager'));const fn=wrap?._pagerHandlers?.[pg.getAttribute('data-dir')];if(fn)return fn()}
  const identitySave=e.target.closest('[data-identity-save]');if(identitySave){identitySave.disabled=true;return saveIdentityUser(identitySave.getAttribute('data-identity-save')).catch(err=>setMsg(err.message||adminT('common.save_failed','Save failed'),true)).finally(()=>{identitySave.disabled=false})}
  const closeChat=e.target.closest('[data-chat-session-close]');if(closeChat){document.getElementById('chatSessionBody')?.remove();return}
  const closeDetail=e.target.closest('[data-account-detail-close]');if(closeDetail){document.querySelectorAll('[data-account-row]').forEach(row=>row.classList.remove('selected'));const el=document.getElementById('accountDetail');if(el)el.innerHTML=adminT('admin.platform.select_account','Select an account to view details.');return}
  const save=e.target.closest('[data-save-limit]');if(save)return saveLimit(save.getAttribute('data-save-limit')).catch(err=>setMsg(err.message||adminT('common.save_failed','Save failed'),true));
  const reset=e.target.closest('[data-reset-limit]');if(reset)return resetLimit(reset.getAttribute('data-reset-limit')).catch(err=>setMsg(err.message||adminT('admin.platform.restore_failed','Restore failed'),true));
  const ad=e.target.closest('[data-account-detail]');if(ad)return openAccountDetail(ad.getAttribute('data-account-detail')).catch(err=>setMsg(err.message||adminT('admin.platform.load_detail_failed','Unable to load details'),true));
  const cs=e.target.closest('[data-chat-session]');if(cs)return openChatSession(cs.getAttribute('data-chat-owner'),cs.getAttribute('data-chat-session')).catch(err=>setMsg(err.message||adminT('admin.platform.load_chat_failed','Unable to load conversation'),true));
  const purge=e.target.closest('[data-purge-guest]');if(purge)return purgeGuestAccount(purge.getAttribute('data-purge-guest')).catch(err=>setMsg(err.message||adminT('admin.platform.purge_guest_failed','Unable to delete guest data'),true));
  const aa=e.target.closest('[data-account-action]');if(aa)return accountAction(aa.getAttribute('data-owner'),aa.getAttribute('data-account-action')).catch(err=>setMsg(err.message||adminT('common.operation_failed','Operation failed'),true));
  const od=e.target.closest('[data-orphan-delete]');if(od)return orphanDelete(od.getAttribute('data-orphan-delete')).catch(err=>setMsg(err.message||adminT('admin.platform.delete_failed','Delete failed'),true));
  const ra=e.target.closest('[data-recycle-action]');if(ra)return recycleAction(ra.getAttribute('data-recycle-id'),ra.getAttribute('data-recycle-action')).catch(err=>setMsg(err.message||adminT('admin.platform.recycle_action_failed','Recycle-bin action failed'),true));
  const br=e.target.closest('[data-backup-restore]');if(br)return restoreBackup(br.getAttribute('data-backup-restore')).catch(err=>setMsg(err.message||adminT('admin.platform.restore_backup_failed','Unable to restore backup'),true));
  const bd=e.target.closest('[data-backup-delete]');if(bd)return deleteBackup(bd.getAttribute('data-backup-delete')).catch(err=>setMsg(err.message||adminT('admin.platform.delete_backup_failed','Unable to delete backup'),true));
});
